/**
 * Uploads file buffers to the Rayvn /files endpoint.
 *
 * Fetches buffers from global context — if no buffer exists the file
 * is recorded as an upload failure.
 *
 * Upload failures are appended to metadata.files.failed.
 * On completion: msg.payload.files = array of Rayvn file IDs.
 */
const target = msg.metadata.target;
const baseUrl = global.get("parat_bridge").base_urls.rayvn;
const utils = global.get("utils");
const items = msg.metadata.files.items;

const resolved = [];
const failed = [];

for (const file of items) {
    const buffer = global.get("files." + file.context_key);

    if (!buffer || buffer.length === 0) {
        node.warn("No buffer for: " + file.context_key);
        failed.push({ name: file.name || "unknown file", reason: utils.FILE_REASONS.UPLOAD_FAILED });
        continue;
    }

    try {
        const boundary = "----PBBoundary" + Date.now();
        const header = `--${boundary}\r\nContent-Disposition: form-data; name="file"; filename="${file.name || "file.bin"}"\r\nContent-Type: ${file.type || "application/octet-stream"}\r\n\r\n`;
        const footer = `\r\n--${boundary}--\r\n`;
        const body = Buffer.concat([Buffer.from(header), buffer, Buffer.from(footer)]);

        const res = await nodeFetch(baseUrl + "/files", {
            method: "POST",
            headers: {
                "Authorization": "Bearer " + target.api_key,
                "Content-Type": "multipart/form-data; boundary=" + boundary
            },
            body
        });

        if (res.ok) {
            const data = await res.json();
            resolved.push(data.id);
            node.log(`File uploaded: ${file.name} → ${data.id}`);
        } else {
            node.warn(`Rayvn /files returned ${res.status} for ${file.name}`);
            failed.push({ name: file.name || "unknown file", reason: utils.FILE_REASONS.UPLOAD_FAILED });
        }
    } catch (e) {
        node.warn(`Error uploading ${file.name}: ${e.message}`);
        failed.push({ name: file.name || "unknown file", reason: utils.FILE_REASONS.UPLOAD_FAILED });
    }
}

msg.payload.files = resolved;

if (failed.length > 0) {
    msg.metadata.files.failed = [
        ...msg.metadata.files.failed,
        ...failed
    ];
}

return msg;

/**
 * Patches msg.payload.text with a receiver notice if any files failed.
 * Runs after upload — metadata.files.failed is the complete failure picture.
 */
const failed = msg.metadata.files.failed;

if (failed.length === 0) return msg;

const succeeded = msg.payload.files.length;
const total = succeeded + failed.length;
const notice = " [" + failed.length + "/" + total
    + " vedlegg ikke overført. Avsender mottar instruks om alternativ håndtering]";

msg.payload.text = (msg.payload.text || "") + notice;

return msg;
